class SafeSortedDestinationRule:
    """Regla refinada: permite destinos seguros y, con relajación controlada, también
    destinos temporales útiles; ordena por preferencia hacia movimientos más prometedores."""

    name = "safe_sorted_destination_rule"

    def __init__(
        self,
        allow_empty_destination=True,
        allow_unsorted_destination=True,
        prefer_empty_destination=False,
        prefer_sorted_destination=True,
        source_badness_weight=1.0,
    ):
        self.allow_empty_destination = allow_empty_destination
        self.allow_unsorted_destination = allow_unsorted_destination
        self.prefer_empty_destination = prefer_empty_destination
        self.prefer_sorted_destination = prefer_sorted_destination
        self.source_badness_weight = float(source_badness_weight)

    def _would_be_sorted(self, partial, so, sd):
        top = partial.g(so)
        if partial.h(sd) == 0:
            return True
        return partial.g(sd) <= top

    def allowed(self, partial, memory, candidates):
        allowed = []
        for a in candidates:
            so = a.so
            sd = a.sd
            if so == sd:
                continue
            if partial.h(so) <= 0:
                continue
            if partial.h(sd) >= partial.H:
                continue

            if partial.h(sd) == 0:
                if not self.allow_empty_destination:
                    continue
            else:
                if (not self.allow_unsorted_destination) and (not self._would_be_sorted(partial, so, sd)):
                    continue

            allowed.append(a)

        return allowed

    def score(self, partial, memory, action):
        so = action.so
        sd = action.sd

        src_top = partial.g(so)
        dst_h = partial.h(sd)
        dst_top = partial.g(sd) if dst_h > 0 else partial.G + 1

        would_be_sorted = self._would_be_sorted(partial, so, sd)

        tier = 3
        if dst_h == 0:
            tier = 0 if self.prefer_empty_destination else 1
        elif would_be_sorted:
            tier = 1 if self.prefer_sorted_destination else 2
        else:
            tier = 2

        # Menor es mejor.
        # Preferimos:
        # 1) destinos vacíos o que permanezcan ordenados;
        # 2) top del destino más pequeño;
        # 3) mover contenedores "más problemáticos" (grupo alto) antes.
        badness_term = -self.source_badness_weight * float(src_top)
        return (
            tier,
            dst_top,
            badness_term,
            sd,
            so,
        )


